import{_ as n,c as i,o as e,ae as s}from"./chunks/framework.BlRNOFgT.js";const p=JSON.parse('{"title":"Latihan Soal: Cloud Computing","description":"","frontmatter":{},"headers":[],"relativePath":"WBD/cloud-computing.md","filePath":"WBD/cloud-computing.md"}'),t={name:"WBD/cloud-computing.md"};function l(r,a,o,u,m,d){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="latihan-soal-cloud-computing" tabindex="-1">Latihan Soal: Cloud Computing <a class="header-anchor" href="#latihan-soal-cloud-computing" aria-label="Permalink to &quot;Latihan Soal: Cloud Computing&quot;">​</a></h1><h2 id="bagian-1-konsep-dasar-karakteristik" tabindex="-1">Bagian 1: Konsep Dasar &amp; Karakteristik <a class="header-anchor" href="#bagian-1-konsep-dasar-karakteristik" aria-label="Permalink to &quot;Bagian 1: Konsep Dasar &amp; Karakteristik&quot;">​</a></h2><p><strong>1. Manakah pernyataan berikut yang secara akurat menggambarkan tantangan provisioning dalam infrastruktur tradisional yang diselesaikan oleh Cloud Computing?</strong></p><ul><li>A. Over-provisioning menyebabkan risiko hilangnya pengguna potensial karena sistem tidak mampu menangani beban puncak.</li><li>B. Rata-rata penggunaan server (utilisasi) di dunia nyata seringkali hanya berkisar antara 5% hingga 20%.</li><li>C. Under-provisioning mengakibatkan capital outlay yang besar menjadi sia-sia karena sumber daya tidak terpakai (idle).</li><li>D. Beban puncak (peak workload) dapat melebihi rata-rata beban kerja hingga faktor 2 sampai 10 kali lipat.</li><li>E. Cloud memungkinkan alokasi sumber daya dimulai dari skala kecil dan bertumbuh sesuai kebutuhan (start small and grow).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D, E</strong></p><p><strong>Penjelasan:</strong> Pengecoh A dan C terbalik. Over-provisioning menyebabkan pemborosan modal (sumber daya idle), sedangkan Under-provisioning menyebabkan hilangnya pengguna (sistem down/lambat).</p></details><hr><p><strong>2. Berdasarkan standar NIST, manakah yang merupakan karakteristik esensial dari Cloud Computing?</strong></p><ul><li>A. Resource Pooling (Penyatuan sumber daya untuk melayani banyak konsumen).</li><li>B. Unlimited Bandwidth (Kapasitas jaringan tanpa batas).</li><li>C. Measured Service (Layanan yang terukur dan dimonitor oleh penyedia).</li><li>D. Rapid Elasticity (Kemampuan untuk melakukan skala naik dan turun dengan cepat).</li><li>E. Single-Tenant Isolation (Setiap hardware didedikasikan untuk satu pengguna saja).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B bukan istilah standar NIST. Opsi E salah karena Cloud menggunakan model Multi-tenant, bukan Single-tenant secara default (Resource Pooling).</p></details><hr><p><strong>3. Mengenai konsep Resource Pooling dan akses jaringan, manakah pernyataan teknis yang valid?</strong></p><ul><li>A. Penyedia cloud menggunakan model multi-tenant untuk melayani konsumen.</li><li>B. Kapabilitas cloud hanya dapat diakses melalui thick clients (seperti desktop powerful), bukan thin clients (seperti mobile/browser).</li><li>C. Ubiquitous Network Access berarti layanan dapat diakses melalui mekanisme standar jaringan.</li><li>D. Lokasi fisik sumber daya (seperti server) selalu diketahui secara pasti dan presisi oleh pengguna akhir setiap saat.</li><li>E. Konsumen dapat menggunakan layanan tanpa interaksi manusia dengan penyedia (On-Demand Self-Service).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B salah karena akses mencakup thick dan thin clients. Opsi D salah karena dalam resource pooling, pengguna seringkali tidak tahu lokasi fisik pasti dari sumber daya (abstraksi lokasi).</p></details><hr><h2 id="bagian-2-model-layanan-spi" tabindex="-1">Bagian 2: Model Layanan (SPI) <a class="header-anchor" href="#bagian-2-model-layanan-spi" aria-label="Permalink to &quot;Bagian 2: Model Layanan (SPI)&quot;">​</a></h2><p><strong>4. Dalam model Infrastructure as a Service (IaaS), komponen mana saja yang menjadi tanggung jawab PENGGUNA (Consumer) untuk dikelola?</strong></p><ul><li>A. Virtualization</li><li>B. Middleware</li><li>C. Runtime</li><li>D. Networking (Fisik)</li><li>E. Data</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Pada IaaS, pengguna mengelola dari OS ke atas (termasuk Middleware, Runtime, Data, App). Penyedia mengelola Virtualization, Servers, Storage, dan Networking. Mahasiswa sering salah mengira Middleware diurus oleh provider di IaaS.</p></details><hr><p><strong>5. Identifikasi pernyataan yang benar mengenai batasan tanggung jawab pada Platform as a Service (PaaS):</strong></p><ul><li>A. Pengguna memiliki kendali penuh atas sistem operasi (O/S).</li><li>B. Pengguna dapat melakukan deploy aplikasi yang dibuat menggunakan bahasa pemrograman yang didukung oleh penyedia.</li><li>C. Penyedia layanan mengelola Runtime dan Middleware.</li><li>D. Google App Engine adalah contoh layanan PaaS yang ditujukan untuk komputasi umum (general purpose computing).</li><li>E. Azure (dalam konteks PaaS) menyediakan lingkungan komputasi umum berbasis platform Microsoft.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena di PaaS, O/S dikelola provider. Opsi D salah karena App Engine dideskripsikan untuk &quot;Build scalable web applications fast&quot;, bukan general purpose computing seperti EC2 (IaaS).</p></details><hr><p><strong>6. Manakah yang merupakan karakteristik dari Software as a Service (SaaS)?</strong></p><ul><li>A. Konsumen tidak perlu mengelola infrastruktur komputasi dasar (server, jaringan).</li><li>B. Aplikasi berjalan pada infrastruktur cloud milik penyedia.</li><li>C. Cocok untuk pengguna yang ingin mengonfigurasi parameter kernel sistem operasi.</li><li>D. Contoh layanannya termasuk Dropbox dan Salesforce.</li><li>E. Semua lapisan dari Networking hingga Applications dikelola oleh penyedia layanan.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi C salah karena SaaS tidak memberikan akses ke level OS atau kernel. Pengguna hanya menggunakan aplikasi jadi.</p></details><hr><h2 id="bagian-3-arsitektur-infrastruktur" tabindex="-1">Bagian 3: Arsitektur &amp; Infrastruktur <a class="header-anchor" href="#bagian-3-arsitektur-infrastruktur" aria-label="Permalink to &quot;Bagian 3: Arsitektur &amp; Infrastruktur&quot;">​</a></h2><p><strong>7. Terkait arsitektur fisik Cloud (Region dan Availability Zone), manakah fakta teknis yang benar?</strong></p><ul><li>A. Region terdiri dari beberapa Availability Zone (AZ) yang terisolasi secara fisik.</li><li>B. Setiap AZ dalam satu region berbagi suplai daya (power) yang sama untuk efisiensi.</li><li>C. Satu AZ dapat terdiri dari satu atau lebih pusat data fisik (physical data centers).</li><li>D. AZ dirancang agar terisolasi satu sama lain dari segi lokasi dan suplai air.</li><li>E. Region adalah lokasi logis, bukan lokasi fisik.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B salah fatal; isolasi AZ justru mensyaratkan sumber daya (power) yang terpisah untuk mencegah kegagalan total. Opsi E salah, Region adalah lokasi fisik geografis.</p></details><hr><p><strong>8. Mengenai teknologi Virtualisasi dan Hypervisor:</strong></p><ul><li>A. Virtualisasi memungkinkan multiple VM berjalan pada satu server fisik tunggal.</li><li>B. Hypervisor Tipe 1 berjalan di atas Sistem Operasi (Hosted).</li><li>C. Hypervisor Tipe 2 dikenal sebagai Bare Metal atau Native.</li><li>D. VMware ESXi dan KVM adalah contoh teknologi yang mengelola alokasi VM.</li><li>E. Hypervisor Tipe 1 menempatkan lapisan virtualisasi langsung di atas Hardware.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi B dan C adalah pengecoh yang menukar definisi. Tipe 1 = Native/Bare Metal (langsung di hardware), Tipe 2 = Hosted (di atas OS).</p></details><hr><p><strong>9. Manakah pernyataan yang tepat mengenai komponen Storage dalam infrastruktur cloud?</strong></p><ul><li>A. Block Storage menyediakan blok penyimpanan mentah, mirip dengan hard drive tradisional.</li><li>B. Object Storage memiliki sistem file hirarkis (seperti folder tree).</li><li>C. File Storage biasanya digunakan untuk sebagian besar kasus penggunaan aplikasi web (web application use cases).</li><li>D. Object Storage menyediakan penyimpanan yang scalable untuk data tidak terstruktur (unstructured data).</li><li>E. SAN dan NAS adalah teknologi yang umum digunakan dalam lingkungan cloud.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi B salah, yang hirarkis adalah File Storage. Opsi C salah, teks menyebutkan Object Storage (bukan File) yang sering digunakan untuk kasus aplikasi web.</p></details><hr><p><strong>10. Dalam konteks jaringan (Networking) cloud, komponen mana saja yang berfungsi untuk menjaga koneksi dan keamanan transfer data?</strong></p><ul><li>A. Load Balancers</li><li>B. Firewalls</li><li>C. Hypervisors</li><li>D. Software-defined networking (SDN)</li><li>E. Virtual Private Networks (VPNs)</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi C salah. Hypervisor adalah komponen komputasi/virtualisasi, bukan komponen jaringan utama untuk transfer data.</p></details><hr><h2 id="bagian-4-manajemen-keamanan-deployment" tabindex="-1">Bagian 4: Manajemen, Keamanan, &amp; Deployment <a class="header-anchor" href="#bagian-4-manajemen-keamanan-deployment" aria-label="Permalink to &quot;Bagian 4: Manajemen, Keamanan, &amp; Deployment&quot;">​</a></h2><p><strong>11. Apa fungsi utama dari platform manajemen cloud (Management and Orchestration)?</strong></p><ul><li>A. Melakukan replikasi data ke lokasi alternatif (Disaster Recovery).</li><li>B. Memfasilitasi provisioning dan alokasi sumber daya.</li><li>C. Mengimplementasikan otomatisasi (automation) untuk efisiensi deployment.</li><li>D. Mengelola penagihan (cost management and billing).</li><li>E. Menyediakan blok penyimpanan mentah untuk database.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A adalah fungsi Disaster Recovery, bukan fungsi utama manajemen platform. Opsi E adalah fungsi Storage. Manajemen fokus pada kontrol, orkestrasi, dan administrasi.</p></details><hr><p><strong>12. Manakah mekanisme yang termasuk dalam komponen Keamanan (Security) infrastruktur cloud?</strong></p><ul><li>A. Intrusion Detection Systems (IDS).</li><li>B. Enkripsi Data (Data Encryption).</li><li>C. Latency Management.</li><li>D. Manajemen Kerentanan (Vulnerability Management).</li><li>E. Kontrol Akses dan Otentikasi.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi C (Latency Management) berkaitan dengan performa/monitoring jaringan, bukan fitur keamanan spesifik secara langsung.</p></details><hr><p><strong>13. Tentukan pernyataan yang benar mengenai model deployment (Public, Private, Hybrid):</strong></p><ul><li>A. Public Cloud infrastrukturnya dioperasikan khusus hanya untuk satu organisasi.</li><li>B. Private Cloud infrastrukturnya tersedia untuk masyarakat umum.</li><li>C. Hybrid Cloud terdiri dari dua atau lebih cloud (private, community, atau public).</li><li>D. Dalam Hybrid Cloud, entitas-entitas cloud tersebut tetap unik tetapi terikat oleh teknologi yang memungkinkan data/aplikasi berpindah (interoperate/federate).</li><li>E. Private Cloud selalu lebih murah daripada Public Cloud karena tidak ada biaya bandwidth.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: C, D</strong></p><p><strong>Penjelasan:</strong> Opsi A dan B definisinya tertukar. Opsi E adalah asumsi ekonomi yang tidak dinyatakan dalam fakta teknis dokumen (dan seringkali salah karena CapEx Private Cloud tinggi).</p></details><hr><h2 id="bagian-5-studi-kasus-pemetaan-layanan" tabindex="-1">Bagian 5: Studi Kasus &amp; Pemetaan Layanan <a class="header-anchor" href="#bagian-5-studi-kasus-pemetaan-layanan" aria-label="Permalink to &quot;Bagian 5: Studi Kasus &amp; Pemetaan Layanan&quot;">​</a></h2><p><strong>14. Anda sedang merancang strategi Disaster Recovery (DR). Aktivitas mana yang relevan dengan komponen ini?</strong></p><ul><li>A. Melakukan replikasi data dan aplikasi ke lokasi alternatif.</li><li>B. Menggunakan Monitoring tools untuk melihat real-time insights.</li><li>C. Membuat salinan data secara berkala (Backup) untuk melindungi dari korupsi data.</li><li>D. Memastikan Failover dan High Availability.</li><li>E. Mengelola Service Value Nets antar bisnis.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B adalah fungsi Monitoring &amp; Analytics. Opsi E berkaitan dengan arsitektur bisnis/Service Value Nets, bukan mekanisme teknis DR.</p></details><hr><p><strong>15. Analisis padanan layanan (Service Mapping) berikut. Manakah pasangan layanan yang setara (equivalent) antar penyedia cloud yang benar?</strong></p><ul><li>A. Google Compute Engine ↔ Amazon EC2 ↔ Azure Virtual Machines.</li><li>B. Google Cloud Functions ↔ AWS Lambda ↔ Azure Functions.</li><li>C. Google Cloud Storage ↔ Amazon S3 ↔ Azure Blob Storage.</li><li>D. Google App Engine ↔ AWS Elastic Beanstalk ↔ Oracle Cloud Infra OCI.</li><li>E. Google Cloud Bigtable ↔ Amazon DynamoDB ↔ Azure Cosmos DB.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi D salah pada bagian Oracle. <em>Google App Engine</em> (PaaS) setara dengan <em>Oracle Application Container</em>, bukan <em>Oracle Cloud Infra OCI</em> (yang merupakan IaaS/VM).</p></details><hr><p><strong>16. Manakah tugas yang termasuk dalam ranah Monitoring and Analytics?</strong></p><ul><li>A. Capacity Planning (Perencanaan kapasitas).</li><li>B. Alerting and Incident Management.</li><li>C. Virtualization (Membuat VM).</li><li>D. Real-time monitoring kesehatan infrastruktur.</li><li>E. Data Privacy Protection.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D</strong></p><p><strong>Penjelasan:</strong> Opsi C adalah fungsi Compute/Virtualization. Opsi E adalah fungsi Compliance/Security. Monitoring fokus pada pelacakan performa dan kesehatan sistem.</p></details><hr><p><strong>17. Berkaitan dengan Compliance and Governance, apa tujuan utama dari komponen ini?</strong></p><ul><li>A. Memastikan kepatuhan terhadap regulasi industri.</li><li>B. Mengelola risiko (Risk management).</li><li>C. Menyediakan load balancing untuk lalu lintas jaringan.</li><li>D. Melakukan audit keamanan dan pelaporan.</li><li>E. Menjamin privasi dan perlindungan data.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, D, E</strong></p><p><strong>Penjelasan:</strong> Opsi C adalah fungsi Networking. Compliance berurusan dengan hukum, aturan, audit, dan kebijakan.</p></details><hr><p><strong>18. Jika Anda menggunakan layanan Oracle Autonomous Data Warehouse, layanan serupa apa yang ditawarkan oleh penyedia cloud lain?</strong></p><ul><li>A. Google BigQuery</li><li>B. Amazon Redshift</li><li>C. Azure Synapse Analytics</li><li>D. Amazon DynamoDB</li><li>E. Google Cloud Datastore</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C</strong></p><p><strong>Penjelasan:</strong> Opsi D dan E adalah layanan NoSQL, sedangkan Data Warehouse (Oracle ADW, Redshift, BigQuery) adalah kategori analisis data skala besar (OLAP/Warehousing), bukan NoSQL transaksional sederhana.</p></details><hr><p><strong>19. Pada diagram Cloud Architecture (Service Value Nets), lapisan mana saja yang terlibat dalam ekosistem cloud?</strong></p><ul><li>A. Service Value Nets</li><li>B. Platform as a Service</li><li>C. Infrastructure as a Service</li><li>D. Business Service &amp; Community Service</li><li>E. Hard Drive Partitioning Service</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, D</strong></p><p><strong>Penjelasan:</strong> Diagram arsitektur menunjukkan lapisan SVN, PaaS, IaaS, serta komponen Business/Community services di dalamnya. Opsi E adalah istilah teknis level rendah yang tidak ada di arsitektur tingkat tinggi ini.</p></details><hr><p><strong>20. Mengapa data center fisik (Physical Data Centers) disebut sebagai fondasi infrastruktur cloud?</strong></p><ul><li>A. Karena mereka menampung perangkat keras yang diperlukan seperti server dan sistem penyimpanan.</li><li>B. Karena mereka menyediakan ruang fisik, daya, dan pendinginan.</li><li>C. Karena desain dan pemeliharaannya menentukan ketersediaan (availability) layanan cloud.</li><li>D. Karena pengguna cloud wajib mengunjungi data center untuk melakukan instalasi server.</li><li>E. Karena mereka mengelola virtualisasi secara otomatis tanpa hypervisor.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C</strong></p><p><strong>Penjelasan:</strong> Opsi D salah total (sifat cloud adalah remote/virtual). Opsi E salah karena virtualisasi dikelola oleh Hypervisor, dan Hypervisor berjalan di atas hardware di dalam data center, bukan data center itu sendiri yang menggantikan hypervisor.</p></details>',85)])])}const k=n(t,[["render",l]]);export{p as __pageData,k as default};
